using System.Net;
using System.Text;
using System.Security.Cryptography;
using Moji.Core;
using Xunit;

namespace Moji.Tests;
public class CryptoTests
{
    [Fact] public void RoundTripAndWrongPassword()
    {var value=new{Password="secret-example-4817",Token="fake-test-token"};using var key=CryptoService.NewKey("Master-Password-2026");var encrypted=CryptoService.Encrypt(value,key);Assert.DoesNotContain(value.Password,Json.Serialize(encrypted));var clear=CryptoService.Decrypt<Dictionary<string,string>>(encrypted,key);Assert.Equal(value.Password,clear["password"]);using var wrong=CryptoService.Derive("wrong",encrypted.Salt,encrypted.Iterations);Assert.Throws<InvalidDataException>(()=>CryptoService.Decrypt<Workspace>(encrypted,wrong));}
    [Fact] public void RandomNonceAndSalt(){using var key=CryptoService.NewKey("password");using var other=CryptoService.NewKey("password");var one=CryptoService.Encrypt(new{Value="same"},key);var two=CryptoService.Encrypt(new{Value="same"},key);Assert.NotEqual(one.Iv,two.Iv);Assert.NotEqual(one.Data,two.Data);Assert.NotEqual(key.Salt,other.Salt);}
    [Fact] public void TamperFailsAuthentication(){using var key=CryptoService.NewKey("password");var e=CryptoService.Encrypt(Seed.Create(),key);var data=Convert.FromBase64String(e.Data);data[0]^=1;Assert.Throws<InvalidDataException>(()=>CryptoService.Decrypt<Workspace>(e with{Data=Convert.ToBase64String(data)},key));}
    [Fact] public void RejectsExcessiveKdf(){Assert.Throws<InvalidDataException>(()=>CryptoService.Derive("pw",Convert.ToBase64String(new byte[16]),int.MaxValue));}
    [Fact] public void PasswordsMeetComposition(){for(var i=0;i<60;i++){var pw=CryptoService.GeneratePassword(32);Assert.Equal(32,pw.Length);Assert.Contains(pw,char.IsLower);Assert.Contains(pw,char.IsUpper);Assert.Contains(pw,char.IsDigit);Assert.Contains(pw,c=>!char.IsLetterOrDigit(c));Assert.All(CryptoService.GeneratePassword(24,false),c=>Assert.True(char.IsAsciiLetterOrDigit(c)));}}
    [Fact] public void KeyIsClearedOnDispose(){var key=CryptoService.NewKey("password");key.Dispose();Assert.Throws<InvalidDataException>(()=>CryptoService.Decrypt<Workspace>(CryptoService.Encrypt(Seed.Create(),CryptoService.NewKey("different")),key));}
}
public class MergeTests
{
    private static SyncPayload Payload(Workspace v)=>new(1,v.Id,v.Notebooks,v.Notes);
    [Fact]public void SingleDeviceEdit(){var local=Seed.Create();var remote=Json.Clone(local).ChangeNote(local.Notes[0].Id,n=>n with{Content="remote"});var merged=WorkspaceMerge.Merge(local,Payload(remote),WorkspaceMerge.Revisions(local));Assert.Equal(local.Notes.Count,merged.Notes.Count);Assert.Equal("remote",merged.Notes[0].Content);Assert.Equal(0,merged.Conflicts);}
    [Fact]public void ConcurrentEditsPreserveBoth(){var original=Seed.Create();var local=original.ChangeNote(original.Notes[0].Id,n=>n with{Content="local"});var remote=original.ChangeNote(original.Notes[0].Id,n=>n with{Content="remote"});var merged=WorkspaceMerge.Merge(local,Payload(remote),WorkspaceMerge.Revisions(original));Assert.Equal(1,merged.Conflicts);Assert.Contains(merged.Notes,n=>n.Content=="local");Assert.Contains(merged.Notes,n=>n.Content=="remote"&&n.Title.EndsWith("同步副本"));}
    [Fact]public void DeletionIsNotResurrected(){var original=Seed.Create();var local=original.ChangeNote(original.Notes[0].Id,n=>n with{DeletedAt=Clock.Now});var merged=WorkspaceMerge.Merge(local,Payload(original),WorkspaceMerge.Revisions(original));Assert.NotNull(merged.Notes[0].DeletedAt);Assert.Equal(0,merged.Conflicts);}
    [Fact]public void DeleteVersusEditRetainsCopy(){var original=Seed.Create();var local=original.ChangeNote(original.Notes[0].Id,n=>n with{DeletedAt=Clock.Now});var remote=original.ChangeNote(original.Notes[0].Id,n=>n with{Content="valuable edit"});var merged=WorkspaceMerge.Merge(local,Payload(remote),WorkspaceMerge.Revisions(original));Assert.NotNull(merged.Notes[0].DeletedAt);Assert.Contains(merged.Notes,n=>n.Content=="valuable edit"&&n.DeletedAt==null);}
    [Fact]public void DeletedNotebookDoesNotHideNotes(){var original=Seed.Create();var book=original.Notebooks[0];var remote=original with{Notebooks=original.Notebooks.Select(b=>b.Id==book.Id?b with{DeletedAt=Clock.Now,UpdatedAt=Clock.Now+10,Revision=Clock.Id}:b).ToList()};var merged=WorkspaceMerge.Merge(original,Payload(remote),WorkspaceMerge.Revisions(original));Assert.NotNull(merged.Notes[0].DeletedAt);}
    [Fact]public void HistoryCapsAndRecovers(){var note=new Note{NotebookId="book",Content="0"};for(var i=1;i<50;i++)note=note.Apply(note with{Content=i.ToString()},true);Assert.Equal(40,note.History.Count);Assert.Equal("48",note.History[0].Content);}
}
public class FeatureTests
{
    [Fact]public void VariablesAreDeduplicated(){Assert.Equal(new[]{"主题","平台"},RecordTools.Variables("{{主题}} {{ 主题 }} {{平台}}"));Assert.Equal("{{平台}} 博客",RecordTools.FillVariables("{{主题}} {{平台}}",new Dictionary<string,string>{{"主题","{{平台}}"},{"平台","博客"}}));}
    [Fact]public void TotpMatchesRfcVector(){Assert.Equal("287082",RecordTools.Totp("GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ",59000));}
    [Fact]public void SearchDoesNotLeakSecret(){var note=new Note{Title="服务",Username="user@example.com",Content="private-note",Password="secret-password",Otp="otp-secret"};Assert.True(RecordTools.Matches(note,"user@example",NoteMode.Password));Assert.False(RecordTools.Matches(note,"secret-password",NoteMode.Password));Assert.False(RecordTools.Matches(note,"private-note",NoteMode.Password));}
    [Fact]public void ValidationRejectsOrphans(){var v=Seed.Create();v.Validate();Assert.Throws<InvalidDataException>(()=>(v with{Notes=[v.Notes[0] with{NotebookId="absent"}]}).Validate());}
    [Fact]public async Task AtomicStoreRetainsEncryptedBackup(){var path=Path.Combine(Path.GetTempPath(),"moji-unit-"+Clock.Id);try{var store=new VaultStore(path);using var key=CryptoService.NewKey("Master-Password-2026");var workspace=Seed.Create();await store.SaveAsync(workspace,key);await store.SaveAsync(workspace.ChangeNote(workspace.Notes[0].Id,n=>n with{Content="new-private-value"}),key);Assert.True(File.Exists(store.VaultPath+".bak"));Assert.DoesNotContain("new-private-value",await File.ReadAllTextAsync(store.VaultPath));var read=await store.ReadAsync();Assert.NotNull(read);Assert.Equal("new-private-value",CryptoService.Decrypt<Workspace>(read,key).Notes[0].Content);await File.WriteAllTextAsync(store.VaultPath,"corrupted");Assert.NotNull(await store.ReadAsync());Assert.True(store.RecoveredBackup);}finally{Directory.Delete(path,true);}}
}
public class SyncTests
{
    [Fact]public async Task RemotePayloadExcludesCredentialsAndWritesOnlyDedicatedDirectory()
    {var state=Seed.Create() with{Sync=new(){Token="fake-test-token",Code="TestSyncCode2026"}};string? body=null;string? target=null;var handler=new FakeHandler(request=>{if(request.Method==HttpMethod.Put){target=request.RequestUri!.AbsoluteUri;body=request.Content!.ReadAsStringAsync().GetAwaiter().GetResult();return new(HttpStatusCode.Created){Content=new StringContent("{}")};}return new(request.RequestUri!.AbsolutePath.EndsWith("xuxian-data")?HttpStatusCode.OK:HttpStatusCode.NotFound){Content=new StringContent("{}")};});await new SyncService(new HttpClient(handler)).SynchronizeAsync(state);Assert.Contains("/contents/moji-notes/",target);using var doc=System.Text.Json.JsonDocument.Parse(body!);var envelope=Json.Deserialize<EncryptedEnvelope>(Encoding.UTF8.GetString(Convert.FromBase64String(doc.RootElement.GetProperty("content").GetString()!)));using var key=CryptoService.Derive(state.Sync.Code,envelope.Salt,envelope.Iterations);var payload=CryptoService.Decrypt<Dictionary<string,System.Text.Json.JsonElement>>(envelope,key);Assert.False(payload.ContainsKey("sync"));Assert.False(payload.ContainsKey("preferences"));}
    [Fact]public async Task ConflictStopsWrite()
    {var state=Seed.Create() with{Sync=new(){Token="fake",Code="TestSyncCode2026"}};using var key=CryptoService.NewKey(state.Sync.Code);var content=Convert.ToBase64String(Encoding.UTF8.GetBytes(Json.Serialize(CryptoService.Encrypt(new SyncPayload(1,state.Id,state.Notebooks,state.Notes),key))));string? body=null;var handler=new FakeHandler(r=>{if(r.Method==HttpMethod.Put){body=r.Content!.ReadAsStringAsync().GetAwaiter().GetResult();return new(HttpStatusCode.Conflict){Content=new StringContent("{}")};}return new(HttpStatusCode.OK){Content=new StringContent(Json.Serialize(new{sha="original-sha",content,size=1000}))};});var error=await Assert.ThrowsAsync<InvalidOperationException>(()=>new SyncService(new HttpClient(handler)).SynchronizeAsync(state));Assert.Contains("重新同步",error.Message);Assert.Contains("original-sha",body);}
    [Fact]public async Task PublicUpdateChecksNeverUseToken()
    {var handler=new FakeHandler(r=>{Assert.Null(r.Headers.Authorization);return new(HttpStatusCode.OK){Content=new StringContent("[]")};});Assert.Null(await new UpdateService(new HttpClient(handler)).CheckAsync(new(1,0,0),"x64"));}
    [Fact]public async Task InvalidDownloadHashNeverInstalls()
    {var asset=new UpdateAsset(1,"Moji-Notes-2.0.0-win-x64.exe","https://github.com/piayboy894/moji-notes/releases/download/v2.0.0/app.exe",4);var hashes=new UpdateAsset(2,"SHA256SUMS.json","https://github.com/piayboy894/moji-notes/releases/download/v2.0.0/SHA256SUMS.json",100);var handler=new FakeHandler(r=>new(HttpStatusCode.OK){Content=new StringContent(r.RequestUri!.AbsolutePath.EndsWith("json")?Json.Serialize(new Dictionary<string,string>{{asset.Name,new string('0',64)}}):"TEST")});var directory=Path.Combine(Path.GetTempPath(),"moji-update-test-"+Clock.Id);try{await Assert.ThrowsAsync<InvalidDataException>(()=>new UpdateService(new HttpClient(handler)).DownloadAsync(new(new(2,0,0),asset,hashes,"https://github.com/piayboy894/moji-notes/releases"),directory));Assert.False(File.Exists(Path.Combine(directory,"Moji.Notes.download.exe")));}finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}}
    private sealed class FakeHandler(Func<HttpRequestMessage,HttpResponseMessage> handle):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken)=>Task.FromResult(handle(request));}
}
